sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* layout */
.row-eq-height { display:flex; flex-wrap:wrap; }
.card-col { display:flex; }
.c-card {
	display:flex; flex-direction:column;
	border:1px solid #e5e5e5; border-radius:4px; background:#fff;
	text-decoration:none; color:inherit; transition:box-shadow .15s ease;
	width:100%; height:100%;
}
.c-card:hover { box-shadow:0 2px 12px rgba(0,0,0,.12); }

/* fixed media height for uniform cards */
.c-card__img {
	flex:0 0 160px; height:160px;
	background-size:cover; background-position:center;
	border-bottom:1px solid #eee; border-top-left-radius:4px; border-top-right-radius:4px;
}

/* body stretches to fill remaining height */
.c-card__body { flex:1 1 auto; display:flex; flex-direction:column; padding:12px; }

/* clamp title/desc to keep heights consistent */
.c-card__title {
	font-weight:600; margin-bottom:6px; line-height:1.2;
	display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden;
	min-height:2.4em;
}
.c-card__desc {
	font-size:12px; line-height:1.4;
	display:-webkit-box; -webkit-line-clamp:3; -webkit-box-orient:vertical; overflow:hidden;
	margin-top:auto;
}

.m-b { margin-bottom:16px; }

sp_widget.script:
(function() {
	data.title = 'Cycloid Stacks';
	data.items = [];

	try {
		var si = new x_1829062_cycloi_1.CycloidIntegration(); // use API name
		var cfg = si._getConfig();
		if (!cfg) { data.error = 'Missing Cycloid configuration.'; return; }

		var stacks = si.getStacks() || [];
		for (var i = 0; i < stacks.length; i++) {
			var s = stacks[i] || {};
			var href = (cfg.console_url || '').replace(/\/+$/,'') +
				'/organizations/' + encodeURIComponent(cfg.org) +
				'/stacks/' + encodeURIComponent(s.ref || '');
			data.items.push({
				name: s.name || 'Unnamed stack',
				desc: (s.description || '').toString(),
				image: s.image || 'https://via.placeholder.com/300x180?text=Cycloid',
				href: href
			});
		}
	} catch (e) {
		data.error = String(e);
	}
})();
